import{_ as r,o as a,c as e,a6 as s}from"./chunks/framework.CGCCzANv.js";const i="/Art_web_public/assets/image-1.B6Vg1U2K.png",_="/Art_web_public/assets/image-2.D1runNan.png",p="/Art_web_public/assets/image.Btkdfd3U.png",o="/Art_web_public/assets/image-3.B5Q6XUJ3.png",b="/Art_web_public/assets/image-4.DKH0OsX2.png",l="/Art_web_public/assets/image-5.Cyn3FxLp.png",n="/Art_web_public/assets/image-9.Zn9VZHAY.png",c="/Art_web_public/assets/image-6.Dofn16o6.png",m="/Art_web_public/assets/image-7.B9J62fEn.png",g="/Art_web_public/assets/image-8.Cm2nedk7.png",P="/Art_web_public/assets/image-10.B4Yh72Kh.png",d="/Art_web_public/assets/image-11.D5OYlBsR.png",k=JSON.parse('{"title":"日式RPG编年史","description":"","frontmatter":{"readingTime":"4 min read"},"headers":[],"relativePath":"游戏引擎/游戏设计/游戏百科/日式RPG编年史/日式RPG编年史.md","filePath":"游戏引擎/游戏设计/游戏百科/日式RPG编年史/日式RPG编年史.md"}'),u={name:"游戏引擎/游戏设计/游戏百科/日式RPG编年史/日式RPG编年史.md"};function h(R,t,G,x,A,f){return a(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="日式rpg编年史" tabindex="-1">日式RPG编年史 <a class="header-anchor" href="#日式rpg编年史" aria-label="Permalink to &quot;日式RPG编年史&quot;">​</a></h1><p>参考：<br><a href="https://www.vgbaike.com/crpg_book_project" target="_blank" rel="noreferrer">https://www.vgbaike.com/crpg_book_project</a></p><p>JRPG扩展了游戏的概念。具有独特的叙事体验。<br> 目前jrpg不是主流的游戏类型，但确在初期深刻建设了日本的“御宅文化”。<br> 1970-1980年代《宇宙战舰大和号》，《机动战士钢弹》，《福星小子》等科幻式幻想世界观，过渡到奇幻幻想世界观。以欧洲中世纪风格的剑与魔法的世界。这个世界是目前宅文化的幻想中心。<br> 这个“国王，勇士，魔王，公主”四个角色组成的故事，是典型的中世纪奇幻故事，但它不属于西方，是经过美国改造，又传入日本继续改造的产物。</p><h2 id="红白机时代" tabindex="-1">红白机时代 <a class="header-anchor" href="#红白机时代" aria-label="Permalink to &quot;红白机时代&quot;">​</a></h2><h3 id="rpg的诞生与黎明期" tabindex="-1">RPG的诞生与黎明期 <a class="header-anchor" href="#rpg的诞生与黎明期" aria-label="Permalink to &quot;RPG的诞生与黎明期&quot;">​</a></h3><p>RPG的最初是1974年的《龙与地下城》，但是一款桌游。后来为了区分，把这个类型叫做TRPG。<br><img src="'+i+'" alt="alt text"></p><p>第一款电脑上的RPG定型确比较困难，受限于立项和发售时间并非有严格考据。最先在柏拉图（PLATO）系统出现<br><img src="'+_+'" alt="alt text"><br> 在柏拉图上的RPG游戏，就已经从机制上开始进化了。<br> 1977年，史上第一款在线多人连线的RPG《ubliette》出现。<br> 有种族与职业，未知道具判定，死亡角色救助等元素<br><img src="'+p+'" alt="alt text"><br><img src="'+o+'" alt="alt text"><br> 经过改良发展出《Avatar》<br> 有转职系统，魔物未知名称等元素<br><img src="'+b+'" alt="alt text"><br> 1981年，在这两款多人线上RPG的基础上，改造成了单人RPG《巫术》。这款游戏也成功将平台移植到了Apple II上<br><img src="'+l+'" alt="alt text"><br> 与此同时，另一个作者理查.盖瑞特，在1977年开发出《DND#1》,这是没有受到柏拉图系统影响的开发路径，更接近文字冒险游戏。<br> 在他1977年推出的下一款游戏《阿卡拉贝：末日世界》中，做出了3D视角RPG，及具有人格的NPC。<br> 在1981年上市的《创世纪》中，通过2D地表大地图和3D地下城的切换，来表现巨大的世界观，并通过NPC之口来讲述故事。奠定了“叙事型RPG”的基础。</p><p>以上这些就是日式RPG诞生的基础。</p><p>在1983-1984年，日本的第一批电子RPG诞生了。</p><p>最早期的日式RPG都是《巫术》和《创世纪》的精神续作，不同的是继承的程度，改良了哪些地方。<br> 但这些游戏所搭载的平台，并不是普通人能拥有的，属于“昂贵的兴趣”。</p><h3 id="勇者斗恶龙的诞生" tabindex="-1">勇者斗恶龙的诞生 <a class="header-anchor" href="#勇者斗恶龙的诞生" aria-label="Permalink to &quot;勇者斗恶龙的诞生&quot;">​</a></h3><p>1986年《勇者斗恶龙》在任天堂红白机上独家上市。而美术风格正是如日中天的鸟山明所设计。<br> 连续三年，《勇者斗恶龙》推出3代作品，销量连续上涨。<br><img src="'+n+'" alt="alt text"><br> 同期其他厂商跟进。 1989年任天堂的《地球冒险》<br><img src="'+c+'" alt="alt text"><br> 南梦宫的《数字恶魔物语 女神转生》,根据西谷史的小说《数字恶魔物语》改编<br><img src="'+m+'" alt="alt text"><br> Data East《重装机兵（Metal Max）》<br><img src="'+g+'" alt="alt text"><br> Hudson Soft的《桃太郎传说》<br><img src="'+P+'" alt="alt text"><br> 在1987年，推出的《最终幻想1》<br><img src="'+d+'" alt="alt text"></p>',12)])])}const D=r(u,[["render",h]]);export{k as __pageData,D as default};
